def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # Vertical markers are the nonzero cells in the bottom two rows.
    marker_cols = {
        c for r in range(max(0, h - 2), h)
        for c in range(w) if grid[r][c] != 0
    }

    for c in marker_cols:
        crossings = []
        for r in range(h):
            row = grid[r]
            nz = [j for j, value in enumerate(row) if value != 0]
            if not nz or not (nz[0] < c < nz[-1]) or row[c] != 0:
                continue
            # This column is a gap inside a horizontal bar. Its color is
            # the color immediately beside the gap.
            color = row[c - 1] if row[c - 1] != 0 else row[c + 1]
            crossings.append((r, color))

        # Each crossing colors the column above it, up to the next crossing.
        for i, (r, color) in enumerate(crossings):
            upper = crossings[i + 1][0] if i + 1 < len(crossings) else -1
            for rr in range(r, upper, -1):
                if grid[rr][c] == 0:
                    out[rr][c] = color

    return out
