def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # Bottom-edge vertical markers identify the columns to extend.
    markers = {}
    for c in range(w):
        for r in range(h - 1, max(-1, h - 4), -1):
            if grid[r][c] != 0:
                markers[c] = grid[r][c]
                break

    for c, marker_color in markers.items():
        crossings = []
        for r in range(h):
            if grid[r][c] != 0:
                continue
            nz = [j for j, value in enumerate(grid[r]) if value != 0]
            if nz and nz[0] < c < nz[-1]:
                color = grid[r][c - 1] if grid[r][c - 1] else grid[r][c + 1]
                crossings.append((r, color))

        if not crossings:
            continue

        # Extend the vertical marker up to the lowest horizontal crossing.
        lowest = crossings[-1][0]
        for r in range(lowest + 1, h):
            if grid[r][c] == 0:
                out[r][c] = marker_color

        # Each horizontal crossing projects its color upward to the next one.
        for i, (r, color) in enumerate(crossings):
            upper = crossings[i - 1][0] if i > 0 else -1
            for rr in range(upper + 1, r + 1):
                if grid[rr][c] == 0:
                    out[rr][c] = color

    return out
